import heapq
from collections import defaultdict


def shortest_paths(edges, source):
    """Dijkstra's algorithm over a list of (u, v, weight) edges."""
    graph = defaultdict(list)
    for u, v, w in edges:
        if w < 0:
            raise ValueError(f"negative weight on edge {u}->{v}: {w}")
        graph[u].append((v, w))
    dist = {source: 0}
    queue = [(0, source)]
    while queue:
        d, u = heapq.heappop(queue)
        if d > dist.get(u, float("inf")):
            continue
        for v, w in graph[u]:
            nd = d + w
            if nd < dist.get(v, float("inf")):
                dist[v] = nd
                heapq.heappush(queue, (nd, v))
    return dist


if __name__ == "__main__":
    print(shortest_paths([("a", "b", 1), ("b", "c", 2), ("a", "c", 5)], "a"))

use std::collections::HashMap;

/// Counts how often each word appears, ignoring case.
pub fn word_counts<'a>(text: &'a str) -> HashMap<String, usize> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for word in text.split_whitespace() {
        let key = word
            .trim_matches(|c: char| !c.is_alphanumeric())
            .to_lowercase();
        if key.is_empty() {
            continue;
        }
        *counts.entry(key).or_insert(0) += 1;
    }
    counts
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn counts_repeated_words() {
        let c = word_counts("The cat and THE dog.");
        assert_eq!(c["the"], 2);
        assert_eq!(c.get("bird"), None);
    }
}
